"""Public supplied photo matching, not gold color or a class-to-row lookup.

Planar feature/homography matching is simulation-photo evidence only, not an
assertion of detection robustness on physical objects, lighting or occlusion.
"""
import base64
import cv2
import numpy as np
PUBLIC_PHOTOS = {'COMMS': '', 'OUTPOST': '', 'RADAR': ''}

class FacilityDetector:
    def __init__(self):
        self.features=cv2.SIFT_create(nfeatures=2000,contrastThreshold=.008,edgeThreshold=12)
        self.matcher=cv2.BFMatcher(cv2.NORM_L2)
        self.references=[]
        for kind,encoded in PUBLIC_PHOTOS.items():
            image=cv2.imdecode(np.frombuffer(base64.b64decode(encoded),np.uint8),cv2.IMREAD_GRAYSCALE)
            for size in (48,72,112,192,320,512):
                scaled=cv2.resize(image,(size,size),interpolation=cv2.INTER_AREA)
                keypoints,descriptors=self.features.detectAndCompute(scaled,None)
                self.references.append((kind,scaled.shape,keypoints,descriptors))
    def detect(self,jpeg):
        image=cv2.imdecode(np.frombuffer(jpeg,np.uint8),cv2.IMREAD_GRAYSCALE)
        if image is None:return []
        height,width=image.shape;keypoints,descriptors=self.features.detectAndCompute(image,None)
        if descriptors is None:return []
        candidates=[]
        for kind,(rh,rw),ref_points,ref_desc in self.references:
            if ref_desc is None:continue
            pairs=self.matcher.knnMatch(ref_desc,descriptors,k=2)
            matches=[p[0] for p in pairs if len(p)==2 and p[0].distance<.75*p[1].distance]
            if len(matches)<8:continue
            source=np.float32([ref_points[m.queryIdx].pt for m in matches]);target=np.float32([keypoints[m.trainIdx].pt for m in matches])
            transform,inliers=cv2.findHomography(source,target,cv2.RANSAC,3.)
            count=int(inliers.sum()) if inliers is not None else 0
            if transform is None or count<7 or count/len(matches)<.55:continue
            quad=cv2.perspectiveTransform(np.float32([[[0,0],[rw-1,0],[rw-1,rh-1],[0,rh-1]]]),transform)[0]
            if not np.isfinite(quad).all() or not cv2.isContourConvex(quad.astype(np.float32)):continue
            edges=np.linalg.norm(quad-np.roll(quad,1,axis=0),axis=1)
            if edges.min()<8 or edges.min()/edges.max()<.15:continue
            area=abs(cv2.contourArea(quad))
            if not 80<area<width*height*.8:continue
            # Local reference geometry: photo center z=.20, height .38, receiver z=.34.
            # Physical camera/emitter extrinsics and receiver placement are uncalibrated.
            receiver=cv2.perspectiveTransform(np.float32([[[rw*.5,rh*(.5-.14/.38)]]]),transform)[0,0]
            if not (-20<receiver[0]<width+20 and -20<receiver[1]<height+20):continue
            x0,y0=quad.min(axis=0);x1,y1=quad.max(axis=0)
            candidates.append({'kind':kind,'cx':float(receiver[0]),'cy':float(receiver[1]),'xyxy':[float(x0),float(y0),float(x1),float(y1)],'width':width,'height':height,'area':float(area),'quad':quad.tolist(),'confidence':count/len(matches),'inliers':count,'method':'provided-photo SIFT/homography; receiver placement is local calibration'})
        unique=[]
        for candidate in sorted(candidates,key=lambda c:-c['inliers']):
            if not any(c['kind']==candidate['kind'] and abs(c['cx']-candidate['cx'])<12 and abs(c['cy']-candidate['cy'])<12 for c in unique):unique.append(candidate)
        return unique
